import React from "react";
import { Card, Image } from "antd";
import no_image from "../../../assets/images/no_image.png";
const { Meta } = Card;

export default function SubscriptionCard({ subscription }) {
  return (
    <Card
      className="m-2"
      hoverable
      style={{
        width: 400,
      }}
      cover={
        <Image
          height={240}
          className="w-8 h-48 object-cover"
          alt="example"
          src={
            subscription && subscription.banners && subscription.banners.length
              ? subscription.banners[0].banner
              : no_image
          }
        />
      }
    >
      <Meta
        title={subscription.title}
        description={
          "KES " + subscription.repayment_amount + " " + subscription.schedule
        }
      />
    </Card>
  );
}
